<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
if(!in_array('--reset-demo',$argv,true)){fwrite(STDERR,"Back up first. Pass --reset-demo to replace demo records.\n");exit(1);}
require __DIR__.'/database.php';$db=mysql_connection();$data=require __DIR__.'/demo-content.php';$demoSkills=require __DIR__.'/demo-skills.php';$catalog=require __DIR__.'/demo-catalog.php';$profiles=require __DIR__.'/demo-profiles.php';
$insert=function($table,$row)use($db){$s=$db->prepare('INSERT INTO `'.$table.'` (`'.implode('`,`',array_keys($row)).'`) VALUES('.implode(',',array_fill(0,count($row),'?')).')');$s->execute(array_values($row));return (int)$db->lastInsertId();};
try{$db->beginTransaction();foreach(['hiring_invitations','applications','resumes','saved','attempts','eprofile','jprofile','euser','juser','categories'] as $table)$db->exec('DELETE FROM '.$table);
$hash=password_hash('HustlersDemo!2026',PASSWORD_DEFAULT);$owners=[];$jobs=[];
foreach($catalog['fields'] as [$field,$avatar])$insert('categories',['name'=>$field,'avatar'=>$avatar]);
foreach($data['companies'] as $i=>[$name,$city,$bio])$owners[]=$insert('euser',['name'=>$name,'company_name'=>$name,'email'=>'employer'.($i+1).'@hustlers.example','password'=>$hash,'role'=>'employer','bio'=>$bio,'location'=>$city,'website'=>$data['companies'][$i][3]??'','title'=>'Portfolio demo account']);
foreach($data['jobs'] as $i=>[$owner,$field,$title,$location,$type,$salary,$experience,$duties,$requirements]){
 $description="ILLUSTRATIVE PORTFOLIO VACANCY — not an official opening or recruitment offer.\n\n".$data['companies'][$owner][2]."\n\nThe role\n".$duties."\n\nWhat we are looking for\n".$requirements."\n\nExperience: ".$experience."\nCompensation: ₹".number_format($salary)." per year".($type==='Contract'?' (annualised contract rate)':'').".\nLocation: ".$location.' · '.$type;
 $jobs[$field][]=$insert('eprofile',['employer_id'=>$owners[$owner],'title'=>$title,'company'=>$data['companies'][$owner][0],'category'=>$field,'location'=>$location,'type'=>$type,'salary'=>$salary,'required_skills'=>$demoSkills['jobs'][$i]??'','description'=>$description,'created_at'=>date('Y-m-d H:i:s',time()-(($i%13)+1)*86400)]);
}
foreach($catalog['candidates'] as $i=>[$name,$field,$title]){$id=$insert('juser',['name'=>$name,'email'=>'seeker'.($i+1).'@hustlers.example','password'=>$hash,'role'=>'seeker','bio'=>'']);$insert('jprofile',array_replace(['user_id'=>$id,'title'=>$title,'field'=>$field,'skills'=>$demoSkills['candidates'][$i]??'','location'=>$data['companies'][$i%count($data['companies'])][1],'bio'=>'Interested in '.$field.'. My recent work focuses on practical testing, clear documentation and making research useful outside the lab.','age'=>$profiles[$i]['age']??null,'experience_years'=>$profiles[$i]['experience_years']??null,'education'=>'Relevant degree and project-based specialist training','work_history'=>'Recent project experience in '.$field.'. Comfortable documenting decisions and collaborating across disciplines.','discoverable'=>1],$profiles[$i]));$insert('applications',['job_id'=>$jobs[$field][0],'user_id'=>$id,'note'=>'I am interested in the practical focus of this role and would be happy to walk through my recent project work.','status'=>['Submitted','Shortlisted','Interview','Closed'][$i%4]]);$insert('saved',['user_id'=>$id,'job_id'=>$jobs[$field][1]??$jobs['Engineering'][0]]);}
foreach(explode(';',file_get_contents(__DIR__.'/avatar-updates.sql')) as $sql)if(trim($sql))$db->exec($sql);
$db->commit();echo "Demo data loaded into euser, juser, eprofile and jprofile.\n";
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
